// Copyright Epic Games, Inc. All Rights Reserved.

#include "GomokuItemLibrary.h"
#include "Misc/AutomationTest.h"

namespace
{
	/** Minimal item data table: maps ItemId -> (Type, Cost, TargetType). */
	struct FStaticItemDef
	{
		int32 Id;
		EGomokuItemType Type;
		int32 EnergyCost;
		EItemTargetType TargetType;
	};

	const TArray<FStaticItemDef>& GetStaticItemDefs()
	{
		static const auto Init = []() {
			TArray<FStaticItemDef> Defs;
			// 1=SealStone, cost1, Cell
			Defs.Add(FStaticItemDef{1, EGomokuItemType::SealStone, 1, EItemTargetType::Cell});
			// 2=Pull (now implemented)
			Defs.Add(FStaticItemDef{2, EGomokuItemType::Pull, 1, EItemTargetType::Cell});
			// 3=Steal
			Defs.Add(FStaticItemDef{3, EGomokuItemType::Steal, 1, EItemTargetType::Cell});
			// 4=SkipTurn (target is player)
			Defs.Add(FStaticItemDef{4, EGomokuItemType::SkipTurn, 1, EItemTargetType::Player});
			// 5=GuardianBarrier
			Defs.Add(FStaticItemDef{5, EGomokuItemType::GuardianBarrier, 1, EItemTargetType::Cell});
			return Defs;
		}();
		return Init;
	}

	const FStaticItemDef* GetItemData(int32 ItemId)
	{
		const auto& Defs = GetStaticItemDefs();
		for (const auto& Def : Defs)
		{
			if (Def.Id == ItemId)
				return &Def;
		}
		return nullptr;
	}

	/** Orthogonal neighbors: N, E, S, W */
	const TArray<FIntPoint> OrthDirections = {FIntPoint(0,-1), FIntPoint(1,0), FIntPoint(0,1), FIntPoint(-1,0)};
}

bool UGomokuItemLibrary::IsRegisteredItemId(int32 ItemId)
{
	return GetItemData(ItemId) != nullptr;
}

bool UGomokuItemLibrary::CanUseItem(UGomokuRuleEngine* Engine, int32 PlayerId, int32 ItemId)
{
	if (!Engine || !Engine->IsMatchInitialized())
		return false;

	if (ItemId <= 0 || PlayerId <= 0)
		return false;

	// Contract: only registered items may be used.
	if (!IsRegisteredItemId(ItemId))
		return false;

	// Stage 7: use IsItemUsableNow instead of raw PlayerHasItem.
	return Engine->IsItemUsableNow(PlayerId, ItemId);
}

bool UGomokuItemLibrary::ValidateTarget(UGomokuRuleEngine* Engine, int32 ItemId, const FIntPoint& TargetCell, int32 TargetPlayerIndex)
{
	if (!Engine || !Engine->IsMatchInitialized())
		return false;
	if (ItemId <= 0)
		return false;

	const auto* Def = GetItemData(ItemId);
	if (!Def)
		return false;

	switch (Def->TargetType)
	{
	case EItemTargetType::Cell:
	{
		if (TargetCell.X < 0 || TargetCell.Y < 0)
			return false;
		if (!Engine->IsValidCoordinate(TargetCell.X, TargetCell.Y))
			return false;

		switch (Def->Type)
		{
		case EGomokuItemType::SealStone:
		{
			const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
			if (C.State != ECellState::Empty) return false;
			break;
		}
		case EGomokuItemType::Steal:
		{
			const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
			// Must be occupied and not Blocked.
			if (C.State == ECellState::Empty || C.State == ECellState::Blocked) return false;
			// Cannot steal self-owned or guardian-protected cells.
			if (Engine->IsCellGuardianProtected(TargetCell.X, TargetCell.Y)) return false;
			break;
		}
		case EGomokuItemType::Pull:
		{
			const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
			// Pull target must be empty.
			if (C.State != ECellState::Empty) return false;

			// Must have at least one orthogonal adjacent opponent stone not guardian-protected.
			bool bHasValidSource = false;
			for (const auto& Dir : OrthDirections)
			{
				const int32 SX = TargetCell.X + Dir.X;
				const int32 SY = TargetCell.Y + Dir.Y;
				if (!Engine->IsValidCoordinate(SX, SY)) continue;

				const auto SC = Engine->GetBoardCell(SX, SY);
				if (SC.State == ECellState::Empty || SC.State == ECellState::Blocked) continue;
				if (Engine->IsCellGuardianProtected(SX, SY)) continue;

				// Opponent stone: owner != PlayerId. We don't have PlayerId here directly,
				// but we know it's not Empty/Blocked and is a player state => valid pull source.
				bHasValidSource = true;
				break;
			}
			if (!bHasValidSource) return false;
			break;
		}
		case EGomokuItemType::GuardianBarrier:
		{
			const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
			if (C.State == ECellState::Empty) return false;
			break;
		}
		default: break;
		}
		return true;
	}
	case EItemTargetType::Player:
	{
		if (TargetPlayerIndex < 0) return false;
		const auto& A = Engine->GetActivePlayerIndices();
		if (TargetPlayerIndex >= A.Num()) return false;
		return true;
	}
	case EItemTargetType::Self:
		return true;
	default:
		return false;
	}
}

bool UGomokuItemLibrary::ExecuteItem(UGomokuRuleEngine* Engine, int32 ItemId, int32 PlayerId, const FIntPoint& TargetCell, int32 TargetPlayerIndex)
{
	if (!Engine || !Engine->IsMatchInitialized()) return false;
	if (ItemId <= 0 || PlayerId <= 0) return false;

	const auto* Def = GetItemData(ItemId);
	if (!Def) return false;

	// Pre-checks: usable + valid target. Fail fast, no side effects.
	if (!Engine->IsItemUsableNow(PlayerId, ItemId)) return false;
	if (!ValidateTarget(Engine, ItemId, TargetCell, TargetPlayerIndex)) return false;

	bool bEffectSucceeded = false;

	switch (Def->Type)
	{
	case EGomokuItemType::SealStone:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State != ECellState::Empty) break;
		if (!Engine->SetCellBlocked(TargetCell.X, TargetCell.Y, true)) break;
		bEffectSucceeded = true;
		break;
	}

	case EGomokuItemType::SkipTurn:
	{
		const int32 TgtId = (TargetPlayerIndex + 1); // matches existing logic.
		if (!Engine->SetPlayerSkipNextTurn(TgtId, true)) break;
		bEffectSucceeded = true;
		break;
	}

	case EGomokuItemType::Steal:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State == ECellState::Empty || C.State == ECellState::Blocked) break;
		if (Engine->IsCellGuardianProtected(TargetCell.X, TargetCell.Y)) break;

		// Change ownership to current player.
		if (!Engine->ChangeCellOwnership(TargetCell.X, TargetCell.Y, PlayerId)) break;

		// Check if this steal created a win line via item effect.
		const FGomokuWinResult WinRes = Engine->CheckWinAt(TargetCell);
		Engine->SetLastItemWinResult(WinRes);

		bEffectSucceeded = true;
		break;
	}

	case EGomokuItemType::Pull:
	{
		// Find first orthogonal adjacent opponent stone not guardian-protected.
		FIntPoint SrcCell(INDEX_NONE, INDEX_NONE);
		int32 SrcOwnerPlayerId = 0;

		for (const auto& Dir : OrthDirections)
		{
			const int32 SX = TargetCell.X + Dir.X;
			const int32 SY = TargetCell.Y + Dir.Y;
			if (!Engine->IsValidCoordinate(SX, SY)) continue;

			const auto SC = Engine->GetBoardCell(SX, SY);
			if (SC.State == ECellState::Empty || SC.State == ECellState::Blocked) continue;
			if (Engine->IsCellGuardianProtected(SX, SY)) continue;

			SrcCell = FIntPoint(SX, SY);
			SrcOwnerPlayerId = UGomokuRuleEngine::CellStateToPlayerId(SC.State);
			break;
		}

		if (SrcCell.X == INDEX_NONE || SrcOwnerPlayerId <= 0) break; // no valid source.

		// Remove stone from source, place at target with same owner.
		if (!Engine->RemoveStoneAt(SrcCell.X, SrcCell.Y)) break;
		if (!Engine->ForcePlaceStone(SrcOwnerPlayerId, TargetCell.X, TargetCell.Y)) break;

		// Clear guardian on source if it was set (API exists).
		Engine->SetCellGuardianProtected(SrcCell.X, SrcCell.Y, false);

		// Check win at target after pull placement.
		const FGomokuWinResult WinRes = Engine->CheckWinAt(TargetCell);
		Engine->SetLastItemWinResult(WinRes);

		bEffectSucceeded = true;
		break;
	}

	case EGomokuItemType::GuardianBarrier:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State == ECellState::Empty) break;
		if (!Engine->SetCellGuardianProtected(TargetCell.X, TargetCell.Y, true)) break;
		bEffectSucceeded = true;
		break;
	}

	default:
	{
		// Unknown or unimplemented item type.
		break;
	}
	}

	if (!bEffectSucceeded)
	{
		return false; // Effect failed: no consume, no remove, no used-flag.
	}

	// Consume energy and inventory only on success (consume-LAST).
	if (!Engine->ConsumePlayerEnergy(PlayerId, Def->EnergyCost)) return false;
	if (!Engine->RemoveItemFromInventory(PlayerId, ItemId)) return false;
	Engine->SetUsedItemThisTurn(PlayerId);

	return true;
}

